case CMD_WRITE:
{
  uint32_t addr = recv_u32();
  uint32_t len = recv_u32();
  uint8_t buf[256];
  uint32_t remaining = len;
  uint32_t offset = 0;

  /* 检查地址范围 */
  if (addr + len > FLASH_SIZE)
  {
    send_nak();
    break;
  }

  /* 擦除需要的扇区 (只擦除一次) */
  uint32_t sector_start = addr & ~(SECTOR_SIZE - 1);
  uint32_t sector_end = (addr + len + SECTOR_SIZE - 1) & ~(SECTOR_SIZE - 1);
  uint32_t sector_addr;
  for (sector_addr = sector_start; sector_addr < sector_end; sector_addr += SECTOR_SIZE)
  {
    d13x_flash_erase_sector(sector_addr);
  }

  /* 连续写入数据 */
  while (remaining > 0)
  {
    uint32_t chunk = remaining > 256 ? 256 : remaining;
    uint32_t i;
    for (i = 0; i < chunk; i++)
      buf[i] = d13x_getc();

    d13x_flash_write(addr + offset, buf, chunk);

    offset += chunk;
    remaining -= chunk;
  }

  send_ack();
  break;
}

