uint32_t d13x_flash_read_id(void)
{
  uint8_t cmd = FLASH_READ_ID;
  uint8_t id[3];
  uint32_t result;

  d13x_spi_cs(1);
  d13x_spi_txrx(&cmd, 0, 1);
  d13x_spi_txrx(0, id, 3);
  d13x_spi_cs(0);

  result = (id[0] << 16) | (id[1] << 8) | id[2];
  return result;
}

uint8_t d13x_flash_read(uint32_t addr, uint8_t *data, int len)
{
  uint8_t cmd[4];
  cmd[0] = FLASH_READ_DATA;
  cmd[1] = (addr >> 16) & 0xFF;
  cmd[2] = (addr >> 8) & 0xFF;
  cmd[3] = addr & 0xFF;

  d13x_spi_cs(1);
  d13x_spi_txrx(cmd, 0, 4);
  d13x_spi_txrx(0, data, len);
  d13x_spi_cs(0);

  return 0;
}

