void __start(void)
{
  /* 保存 BROM 传入的启动参数 (a0, a1) */

  __asm__ __volatile__(
    "la t0, boot_params_stash\n"
    "sw a0, 0(t0)\n"       /* boot_device/boot_reason */
    "sw a1, 4(t0)\n"       /* private_data address */
    "sw a2, 8(t0)\n"
    "sw a3, 12(t0)\n"
    "sw a4, 16(t0)\n"
    "sw a5, 20(t0)\n"
    "sw a6, 24(t0)\n"
    "sw a7, 28(t0)\n"
    "sw s0, 32(t0)\n"
    "sw s1, 36(t0)\n"
    "sw s2, 40(t0)\n"
    "sw s3, 44(t0)\n"
    "sw s4, 48(t0)\n"
    "sw s5, 52(t0)\n"
    "sw s6, 56(t0)\n"
    "sw s7, 60(t0)\n"
    "sw s8, 64(t0)\n"
    "sw s9, 68(t0)\n"
    "sw s10, 72(t0)\n"
    "sw s11, 76(t0)\n"
    "sw sp, 80(t0)\n"
    "sw ra, 84(t0)\n"
    ::: "memory"
  );

  /* 拷贝 boot_arg (256 字节) */

  if (boot_params_stash[1] != 0)
    {
      uint32_t *src = (uint32_t *)boot_params_stash[1];
      uint32_t *dst = boot_arg;
      int i;
      for (i = 0; i < 64; i++)
        {
          dst[i] = src[i];
        }
    }

  /* 清除 BSS 段 */

  uint32_t *ptr;

  for (ptr = _sbss; ptr < _ebss; ptr++)
    {
      *ptr = 0;
    }

  /* 拷贝 .data 段 */

  for (ptr = _sdata; ptr < _edata; ptr++)
    {
      *ptr = *(_eronly + (ptr - _sdata));
    }

  /* 初始化系统时钟 */

  d13x_clock_init();

  /* 初始化 UART0 */

  d13x_uart_init();

  /* 打印启动信息 */

  uint32_t boot_dev = get_boot_device(boot_params_stash[0]);
  uint32_t boot_reason = get_boot_reason(boot_params_stash[0]);
  putreg32('D' + (boot_dev << 8) + (boot_reason << 16), D13X_UART0_BASE + UART_RBR_THR_DLL);

  /* 启动 NuttX */

  nx_start();

  /* 不应到达此处 */

  for (; ; );
}

