static void print_str(const char *str)
{
  while (*str)
    d13x_putc(*str++);
}

static void print_hex(uint32_t val)
{
  int i;
  char buf[9];
  for (i = 7; i >= 0; i--)
  {
    int nibble = (val >> (i * 4)) & 0xF;
    buf[7 - i] = nibble < 10 ? '0' + nibble : 'A' + nibble - 10;
  }
  buf[8] = '\0';
  print_str("0x");
  print_str(buf);
}

